"""AUTO-GENERATED rule: mentor_tribal.

Generated by scripts/scaffold_rule.py from template
'peer_tribal_keyword' on the keyword 'Mentor'. Surfaces the
small-pool of cards sharing this keyword as natural archetype
partners.

Auditor context at generation time:
- Reach: 5 commanders carrying keyword.Mentor
- Currently uncovered: 5
- Pool: 19 cards with this keyword
"""

from __future__ import annotations

import sqlite3

from ..core import PortComplement, PortRow

#: The keyword this rule fires on. Single-keyword scope by design —
#: each new keyword scaffolds its own module so reverts stay isolated.
_KEYWORD = "Mentor"


def _mentor_tribal_gate(port: PortRow) -> bool:
    """True iff ``port`` is a keyword port for the target keyword."""
    if (port.get("port_type") or "").strip() != "keyword":
        return False
    return (port.get("event_class") or "").strip() == _KEYWORD


def _find_mentor_tribal(
    conn: sqlite3.Connection,
    cmdr_ports: list[PortRow],
    cmdr_set: set[str],
) -> list[PortComplement]:
    """Return every other card carrying the same keyword.

    Pool is small by gate construction (auditor only proposes this
    template for keywords with <=100 cards), so IDF naturally rewards
    these matches without needing a hand-tuned multiplier.
    """
    if not any(_mentor_tribal_gate(p) for p in cmdr_ports):
        return []

    rows = conn.execute(
        "SELECT DISTINCT card_name FROM card_ports WHERE port_type = 'keyword' AND event_class = ?",
        (_KEYWORD,),
    )
    results: list[PortComplement] = []
    for row in rows:
        name = row["card_name"]
        if name in cmdr_set:
            continue
        results.append(
            PortComplement(
                rule_id="mentor_tribal",
                direction="synergy",
                candidate=name,
                cmdr_event="mentor_tribal",
                cand_event="same_keyword_partner",
            )
        )
    return results
